        "lnKcxanCqxdXvGZG": {
          "name": "Escudo de Cerco",
          "description": "Enquanto estiver adjacente a uma arma de cerco, o artilheiro ganha +1 de bônus de circunstância na CA."
        },
        "BKAZUyxs7ojI3Lc0": {
          "name": "Especialista em armas de cerco",
          "description": "O artilheiro ganha +2 de bônus para testar (percepção, opções: arma de cerco) se o artilheiro estiver tripulando uma arma de cerco. Além disso, eles ganham um bônus de +2 para testes (conhecimento de engenharia, opções: arma de cerco) e testes (conhecimento de explosivos, opções: arma de cerco) para armas de cerco."
        },
        "axHGPBgPqDgvP4Ej": {
          "name": "Bombardear",
          "description": "O artilheiro ativa uma peça de artilharia montada no ombro para lançar um projétil explosivo até 120 pés (36 metros) que explode em um tipo de explosão de 3 metros. As criaturas dentro da explosão sofrem 2d6 de dano perfurante | opções: dano de área] de dano com um teste de resistência (reflexo, dc: 19, básico, opções: efeito de área, inflige: caído). Uma criatura que falhar no teste também será derrubada. O artilheiro não pode usar Bombardear novamente até recarregar a artilharia com 2 ações de Interação; essas ações não precisam ser consecutivas."
        }
