      "name": "Sibila",
      "description": "Sibilas são adivinhos oraculares que muitas vezes caem profundamente em transe com suas maldições oraculares para estimular um estado mental frenético. Nesse transe, eles se conectam com deuses e espíritos, ainda que numa névoa desorganizada. Algumas falsas sibilas usarão substâncias para tentar estabelecer essa mesma conexão frenética, muitas vezes com resultados mortais.\nAs religiões inspiram indivíduos devotos a defender seus princípios.",
