      "name": "Cronista",
      "description": "A exploração significa muito pouco se não existir nenhum relato dos detalhes. Membros de bandos de aventureiros apreciam cronistas que registram histórias de seus feitos.\nO mundo é um lugar amplo e aberto, repleto de perigos e aventuras. Os exploradores usam seu conhecimento da natureza e habilidades de sobrevivência para ver cada canto da terra.",
