      "actions": {
        "erUOYsgrGptiiYkw": {
          "name": "Ossos chocalhando",
          "description": "Gatilho A mãe osso ou outro povo-rato em seu quadrado sofre dano de um ataque corpo a corpo\nEfeito Espíritos dos ossos emergem para causar 2d6 de dano espiritual ao atacante com um teste de resistência (vontade, dc:24, básico)."
        },
        "0lO5biVc23eHTzsk": {
          "name": "Enxameação",
          "description": "Um ysoki pode terminar seu movimento no mesmo quadrado que um aliado que também possui essa habilidade. Apenas duas dessas criaturas podem compartilhar o mesmo espaço."
        }
      },
